const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([104.238631, 40.923221]);
  const region = point.buffer(50000); // 50km radius

  // 2. Data Acquisition
  const feb2019 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .filterDate('2019-02-01', '2019-03-01')
    .filterBounds(region);

  const feb2020 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .filterDate('2020-02-01', '2020-03-01')
    .filterBounds(region);

  // Check collection sizes
  const count2019 = feb2019.size().getInfo();
  const count2020 = feb2020.size().getInfo();

  console.log(`Feb 2019 Images: ${count2019}`);
  console.log(`Feb 2020 Images: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites and mask poor quality
  const composite2019 = feb2019
    .select('aerosol_index')
    .mean()
    .updateMask(feb2019.select('qa_value').mean().gt(0.5));

  const composite2020 = feb2020
    .select('aerosol_index')
    .mean()
    .updateMask(feb2020.select('qa_value').mean().gt(0.5));

  // 4. Calculate statistics
  const stats2019 = composite2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2020 = composite2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean2019 = stats2019.get('aerosol_index').getInfo();
  const countPixels2019 = stats2019.get('aerosol_index_count').getInfo();
  const mean2020 = stats2020.get('aerosol_index').getInfo();
  const countPixels2020 = stats2020.get('aerosol_index_count').getInfo();

  console.log(`2019 Mean AI: ${mean2019?.toFixed(3)}, Pixels: ${countPixels2019}`);
  console.log(`2020 Mean AI: ${mean2020?.toFixed(3)}, Pixels: ${countPixels2020}`);

  // 5. Validation & Final Answer
  if (countPixels2019 === 0 || countPixels2020 === 0) {
    console.log("<answer>C2</answer>");
  } else if (mean2019 === null || mean2020 === null || 
             isNaN(mean2019) || isNaN(mean2020) ||
             mean2019 > 10 || mean2020 > 10) { // Unrealistic aerosol index values
    console.log("<answer>C3</answer>");
  } else if (mean2020 > mean2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
